/**
 * A shipment's single lifecycle: we set AWAITING then SHIPPED; the carrier advances IN_TRANSIT →
 * OUT_FOR_DELIVERY → DELIVERED via tracking. RETURNED/FAILURE are carrier terminal off-ramps; CANCELLED
 * is an admin override.
 */
export enum ShipmentStatus {
  Awaiting = 'AWAITING',
  Cancelled = 'CANCELLED',
  Delivered = 'DELIVERED',
  Failure = 'FAILURE',
  InTransit = 'IN_TRANSIT',
  OutForDelivery = 'OUT_FOR_DELIVERY',
  Returned = 'RETURNED',
  Shipped = 'SHIPPED',
  UnableToPackage = 'UNABLE_TO_PACKAGE'
}

