/** An audit log entry recording a single change to a translation */
export type TranslationHistory = {
  __typename?: 'TranslationHistory';
  /** Principal ID of the actor, null for system/AI-driven changes */
  changedBy?: Maybe<Scalars['UUID']['output']>;
  /** Timestamp when this entry was created */
  created: Scalars['DateTime']['output'];
  /** Previous state (null for the initial entry) */
  fromState?: Maybe<TranslationState>;
  /** Unique identifier */
  id: Scalars['UUID']['output'];
  /** Text after this change */
  newText: Scalars['String']['output'];
  /** Provenance of the change */
  origin: TranslationOrigin;
  /** Optional origin detail (AI model name, Crowdin user, etc.) */
  originDetail?: Maybe<Scalars['String']['output']>;
  /** Text before this change, or null for the initial entry */
  previousText?: Maybe<Scalars['String']['output']>;
  /** Which table the translation_id refers to (translations | plural_translations | document_translations) */
  tableName: Scalars['String']['output'];
  /** New state resulting from this change */
  toState: TranslationState;
  /** ID of the translation this entry describes */
  translationId: Scalars['UUID']['output'];
};

/** Identifies the source that produced a translation */
export enum TranslationOrigin {
  /** Generated by an AI pipeline */
  Ai = 'AI',
  /** Entered directly by a human translator */
  Human = 'HUMAN',
  /** Loaded from a source file via the CLI or API */
  Import = 'IMPORT',
  /** Pulled from an external sync platform such as Crowdin */
  Sync = 'SYNC'
}

/** Aggregate progress counters for a project+language pair */
export type TranslationProgress = {
  __typename?: 'TranslationProgress';
  /** Strings whose current translation originated from AI */
  aiGeneratedStrings: Scalars['Int']['output'];
  /** Strings whose translation is approved or published */
  approvedStrings: Scalars['Int']['output'];
  /** Strings whose current translation originated from a human */
  humanTranslatedStrings: Scalars['Int']['output'];
  /** Translated strings as a percentage of total strings (0-100) */
  percentage: Scalars['Float']['output'];
  /** Strings whose translation is published */
  publishedStrings: Scalars['Int']['output'];
  /** Total translatable strings in the project */
  totalStrings: Scalars['Int']['output'];
  /** Strings that have any translation (regardless of state) */
  translatedStrings: Scalars['Int']['output'];
};

/** Workflow state identifying where a translation is in the review lifecycle */
export enum TranslationState {
  /** Produced by an AI pipeline; requires human review before publishing */
  AiGenerated = 'AI_GENERATED',
  /** Reviewed and approved; ready for publishing */
  Approved = 'APPROVED',
  /** No longer active; soft-removed */
  Archived = 'ARCHIVED',
  /** Initial state for newly created or imported human translations */
  Draft = 'DRAFT',
  /** Submitted for human review */
  InReview = 'IN_REVIEW',
  /** Live; eligible for export */
  Published = 'PUBLISHED',
  /** Failed review; returned to draft for rework */
  Rejected = 'REJECTED'
}

