/**
 * R13 — SLA policies, goals, working calendars, and the per-task
 * state the tick job mutates. Calendars hold weekly hours and
 * holidays as JSON; the evaluator interprets them with the calendar's
 * time zone.
 */
export type WorkOpsWorkingCalendar = {
  __typename?: 'WorkOpsWorkingCalendar';
  description?: Maybe<Scalars['String']['output']>;
  /** `[YYYY-MM-DD, ...]` — dates excluded from working hours. */
  holidays: Scalars['JSON']['output'];
  id: Scalars['UUID']['output'];
  name: Scalars['String']['output'];
  timeZone: Scalars['String']['output'];
  version: Scalars['Long']['output'];
  /**
   * `Map<DayOfWeek, [{startLocal, endLocal}]>` — keys are uppercase
   * English day names. `endLocal` of `24:00` means end-of-day.
   */
  weeklyHours: Scalars['JSON']['output'];
};

export type WorkOpsWorkingCalendarInput = {
  description?: InputMaybe<Scalars['String']['input']>;
  holidays: Scalars['JSON']['input'];
  name: Scalars['String']['input'];
  timeZone: Scalars['String']['input'];
  weeklyHours: Scalars['JSON']['input'];
};

